 const groupLabels={'bachelor-semester-overall-policy-ceiling':'Overall transfer limits · online bachelor’s','bachelor-online-semester-course-provider-policy-ceiling':'Alternative-course limits · online bachelor’s','bachelor-online-semester-residency-arithmetic-bound':'University-credit minimum · online bachelor’s','bachelor-online-competency-unit-project-management-theoretical-bound':'Competency units · WGU Project Management'};
