 function fallbackProfile(name){const route=(root.DegreeProgramCatalog.publishedPlans?.(catalog)||[]).find(item=>norm(item.school)===norm(name));return{id:root.DegreeReadyTemplates.canonicalSchoolId(name,route?.schoolId),name,summary:'Explore the available course plans for this school.',pros:[],tradeoffs:[],sources:[],pace:{label:'Program-specific schedule'},recognition:{status:'not-reviewed'},reviews:{count:0},scope:{levels:[],modalities:[]}};}
