 async function mountDiscussion(){if(!root.DegreeCommunity||!profile)return;const schoolId=profile.id;try{const result=await root.DegreeCommunity.mountContext($('school-discussion'),{context:'school:'+schoolId,title:'Student experiences and questions'});if(profile?.id===schoolId)mounted=result;else result?.destroy?.();}catch{/* The discussion link remains available. */}}
 async function request(path,method,body){const r=await root.fetch(path,{method:method||'GET',credentials:'same-origin',headers:{Accept:'application/json',...(method&&method!=='GET'?{'Content-Type':'application/json','X-Portal-Request':'1'}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});let value;try{value=await r.json();}catch{throw Error('This service is temporarily unavailable. Please try again.');}if(!r.ok)throw Error(value.error||'This request could not be completed.');return value;}
