   if(/^[A-Za-z0-9_-]{1,100}$/.test(templateId||'')){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const response=await root.fetch('/api/templates/'+encodeURIComponent(templateId),{credentials:'same-origin',signal:controller.signal});if(response.ok){const result=await response.json();extraPlans=root.DegreeReadyTemplates.fromReviewed([result.template],root.DegreeProgramCatalog,catalog).filter(item=>norm(item.schoolName)===norm(wanted)).map(item=>({id:item.pathwayId,modelId:item.modelId,school:item.schoolName,title:item.title,level:item.level,modalities:item.modalities,degreeCredits:item.creditFacts.totalCredits,launchURL:item.launchURL,openCourseChoices:item.openCourseChoices}));}}catch{}finally{clearTimeout(timer);}}
